module mst_mht_weight (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire [7:0] x0, x1, x2, x3, x4, x5, x6, x7,\n    input wire [7:0] y0, y1, y2, y3, y4, y5, y6, y7,\n    output reg [11:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE         = 3'd0;\n    localparam [2:0] INIT         = 3'd1;\n    localparam [2:0] FIND_MIN     = 3'd2;\n    localparam [2:0] ADD_VERTEX   = 3'd3;\n    localparam [2:0] UPDATE_DIST  = 3'd4;\n    localparam [2:0] DONE_STATE   = 3'd5;\n\n    reg [2:0] state, next_state;\n    reg [2:0] iter_count;\n    reg [7:0] visited;\n    reg [11:0] min_dist [0:7];\n    reg [2:0] current_vertex;\n    reg [7:0] x_reg[0:7];   // Registered x coords\n    reg [7:0] y_reg[0:7];   // Registered y coords\n    reg [2:0] update_idx;\n    reg [2:0] min_index;\n    reg [11:0] min_distance;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n\n    // Manhattan distance function\n    function automatic [11:0] manhattan_dist;\n        input [7:0] x1, y1;\n        input [7:0] x2, y2;\n        reg [8:0] dx, dy;\n        begin\n            dx = (x1 > x2) ? (x1 - x2) : (x2 - x1);\n            dy = (y1 > y2) ? (y1 - y2) : (y2 - y1);\n            manhattan_dist = dx + dy;\n        end\n    endfunction\n\n    integer i;  // Loop variable\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 12'd0;\n            done <= 1'b0;\n            iter_count <= 3'd0;\n            cycle_count <= 8'd0;\n            visited <= 8'd0;\n            current_vertex <= 3'd0;\n            min_index <= 3'd0;\n            min_distance <= 12'hFFF;\n            for (i = 0; i < 8; i = i + 1) begin\n                min_dist[i] <= 12'hFFF;  // Initialize to max\n                x_reg[i] <= 8'd0;\n                y_reg[i] <= 8'd0;\n            end\n        end else begin\n            cycle_count <= cycle_count + 8'd1;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        cycle_count <= 8'd0;\n                        result <= 12'd0;\n                        visited <= 8'd0;\n                        // Load input points into registers\n                        x_reg[0] <= x0; x_reg[1] <= x1; x_reg[2] <= x2; x_reg[3] <= x3;\n                        x_reg[4] <= x4; x_reg[5] <= x5; x_reg[6] <= x6; x_reg[7] <= x7;\n                        y_reg[0] <= y0; y_reg[1] <= y1; y_reg[2] <= y2; y_reg[3] <= y3;\n                        y_reg[4] <= y4; y_reg[5] <= y5; y_reg[6] <= y6; y_reg[7] <= y7;\n                        \n                        state <= INIT;\n                    end\n                end\n                \n                INIT: begin\n                    // Start with vertex 0\n                    visited[0] <= 1'b1;\n                    iter_count <= 3'd0;\n                    min_dist[0] <= 12'd0;\n                    current_vertex <= 3'd0;\n                    update_idx <= 3'd0;\n                    state <= UPDATE_DIST;\n                end\n                \n                UPDATE_DIST: begin\n                    if (update_idx < 3'd7) update_idx <= update_idx + 3'd1;\n                    \n                    if (!visited[update_idx] && (update_idx < N)) begin\n                        min_dist[update_idx] <= manhattan_dist(\n                            x_reg[current_vertex], y_reg[current_vertex],\n                            x_reg[update_idx], y_reg[update_idx]\n                        );\n                    end\n                    \n                    if (update_idx == (N - 3'd1) || cycle_count >= MAX_CYCLES) begin\n                        state <= FIND_MIN;\n                        update_idx <= 3'd0;\n                        min_distance <= 12'hFFF;\n                        min_index <= 3'd0;\n                    end\n                end\n                \n                FIND_MIN: begin\n                    if (update_idx < N) begin\n                        if (!visited[update_idx] && (min_dist[update_idx] < min_distance)) begin\n                            min_distance <= min_dist[update_idx];\n                            min_index <= update_idx;\n                        end\n                        update_idx <= update_idx + 3'd1;\n                    end else begin\n                        if (min_distance == 12'hFFF || cycle_count >= MAX_CYCLES) begin\n                            state <= DONE_STATE;  // All vertices visited\n                        end else begin\n                            state <= ADD_VERTEX;\n                        end\n                        update_idx <= 3'd0;\n                    end\n                end\n                \n                ADD_VERTEX: begin\n                    result <= result + min_distance;\n                    visited[min_index] <= 1'b1;\n                    current_vertex <= min_index;\n                    iter_count <= iter_count + 3'd1;\n                    \n                    if (iter_count == (N - 3'd2)) begin  // Done N-1 times\n                        state <= DONE_STATE;\n                    end else begin\n                        state <= UPDATE_DIST;\n                        update_idx <= 3'd0;\n                        min_distance <= 12'hFFF;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule